#requires -Version 5.1
# 探针：确认屏幕是否有第二个渲染者（apc1/其它任务）。
# 步骤：ps → 记下 zhaoxi_ui 的 PID → kill → 监听 12 秒 PANDBG → 输出全部捕获。
param([string]$Port = 'COM3', [int]$Baud = 921600)

$ErrorActionPreference = 'Stop'
$Buf = New-Object System.Text.StringBuilder

function Read-Avail([System.IO.Ports.SerialPort]$sp, [int]$ms) {
    $sw = [Diagnostics.Stopwatch]::StartNew()
    while ($sw.ElapsedMilliseconds -lt $ms) {
        try { $c = $sp.ReadExisting() } catch { Start-Sleep -Milliseconds 50; continue }
        if ($c) { [void]$Buf.Append($c) } else { Start-Sleep -Milliseconds 30 }
    }
}

function Wait-Prompt([System.IO.Ports.SerialPort]$sp, [int]$timeoutMs) {
    $sw = [Diagnostics.Stopwatch]::StartNew()
    while ($sw.ElapsedMilliseconds -lt $timeoutMs) {
        try { $c = $sp.ReadExisting() } catch { Start-Sleep -Milliseconds 50; continue }
        if ($c) {
            [void]$Buf.Append($c)
            $t = $Buf.ToString()
            if ($t -match '(nsh|ap|vela)>[\s\x1b\[\]0-9;A-Za-z]*$') { return $Matches[1] }
        } else { Start-Sleep -Milliseconds 30 }
    }
    return $null
}

function Send-Cmd([System.IO.Ports.SerialPort]$sp, [string]$cmd, [int]$timeoutMs = 6000) {
    [void]$Buf.Clear()
    $bytes = $sp.Encoding.GetBytes($cmd + "`n")
    for ($off = 0; $off -lt $bytes.Length; $off += 32) {
        $len = [Math]::Min(32, $bytes.Length - $off)
        $sp.Write($bytes, $off, $len)
        Start-Sleep -Milliseconds 30
    }
    return (Wait-Prompt $sp $timeoutMs)
}

$sp = New-Object System.IO.Ports.SerialPort($Port, $Baud, [System.IO.Ports.Parity]::None, 8, [System.IO.Ports.StopBits]::One)
$sp.Encoding = New-Object System.Text.UTF8Encoding($false)
$sp.NewLine = "`n"
$sp.ReadTimeout = 500
$sp.WriteTimeout = 2000
$sp.ReadBufferSize = 1048576
$sp.Handshake = [System.IO.Ports.Handshake]::None
try { $sp.Open() } catch { Write-Host "ERROR: 打不开串口 $Port ($($_.Exception.Message))"; exit 1 }

try {
    [void]$Buf.Clear()
    $sp.Write("`n")
    $p = Wait-Prompt $sp 8000
    if ($null -eq $p) { $sp.Write("`n"); $p = Wait-Prompt $sp 8000 }
    if ($null -eq $p) { Write-Host 'ERROR: 无提示符'; exit 1 }
    Write-Host "PROMPT=$p"
    if ($p -eq 'vela') {
        $sp.Write("quit`n"); $p = Wait-Prompt $sp 15000
        Write-Host "AFTER_QUIT=$p"
    }

    # 1) ps：找 zhaoxi_ui 及其他可疑渲染任务
    $p = Send-Cmd $sp 'ps' 8000
    $psOut = $Buf.ToString()
    Write-Host '===== PS BEGIN ====='
    Write-Host $psOut
    Write-Host '===== PS END ====='

    $zpid = $null
    foreach ($ln in ($psOut -split "`n")) {
        if ($ln -match 'zhaoxi_ui' -and $ln -match '^\s*(\d+)') { $zpid = $Matches[1] }
    }
    Write-Host "ZHAOXI_PID=$zpid"

    # 2) 板端时间（与屏幕时钟对照）
    $p = Send-Cmd $sp 'date' 6000
    Write-Host '===== DATE ====='
    Write-Host $Buf.ToString()

    # 3) kill zhaoxi_ui
    if ($zpid) {
        $p = Send-Cmd $sp "kill $zpid" 6000
        Write-Host "KILL_RESP_PROMPT=$p"
        Write-Host $Buf.ToString()
    }

    # 4) 监听 12 秒：PANDBG 还来不来、从哪个任务来
    [void]$Buf.Clear()
    Read-Avail $sp 12000
    Write-Host '===== POSTKILL 12s BEGIN ====='
    Write-Host $Buf.ToString()
    Write-Host '===== POSTKILL 12s END ====='

    # 5) 再 ps 一次确认已死
    $p = Send-Cmd $sp 'ps' 8000
    Write-Host '===== PS2 BEGIN ====='
    Write-Host $Buf.ToString()
    Write-Host '===== PS2 END ====='
} finally {
    $sp.Close()
}

