+    int count = 0;
+    char line[256];
+    while (fgets(line, sizeof(line), fp) != NULL) {
+        const char *p = line;
+        while (*p == ' ' || *p == '\t') p++;
+        if (strncmp(p, "- [ ]", 5) == 0) {
+            count++;
