            }
            else if((touch_flags & TOUCH_UP) && primary_index >= 0) {
                break;
            }
        }
        else if((touch_flags & (TOUCH_DOWN | TOUCH_MOVE)) && primary_index < 0) {
            primary_index = i;
        }
    }

    if(primary_index != -1) {
        touchscreen->primary_point.id = sample->point[primary_index].id;
