# Parse font cmap coverage
function Get-FontCoverage([string]$path) {
    $txt = [IO.File]::ReadAllText($path, [Text.Encoding]::UTF8)
    $cov = New-Object System.Collections.Generic.HashSet[int]
    # sparse list entries like 0x4E00, (in unicode_list / glyph_dsc)
    foreach ($m in [regex]::Matches($txt, '0x([0-9A-Fa-f]{4})')) {
        [void]$cov.Add([Convert]::ToInt32($m.Groups[1].Value, 16))
    }
    # contiguous ranges: .range_start = N, .range_length = L
    foreach ($m in [regex]::Matches($txt, 'range_start\s*=\s*(\d+)\s*,\s*\.range_length\s*=\s*(\d+)')) {
        $start = [int]$m.Groups[1].Value; $len = [int]$m.Groups[2].Value
        for ($i = 0; $i -lt $len; $i++) { [void]$cov.Add($start + $i) }
    }
    return $cov
}

