static bool read_first_line_from(const char *path, char *buf, size_t buflen)
{
    FILE *fp = fopen(path, "r");
    if (fp == NULL) return false;

    bool ok = false;
    while (fgets(buf, (int)buflen, fp) != NULL) {
        size_t n = strlen(buf);
        while (n > 0 && (buf[n - 1] == '\n' || buf[n - 1] == '\r')) {
            buf[--n] = '\0';
        }
        if (n > 0) {
            ok = true;
            break;
        }
    }
    fclose(fp);
    return ok;
}

