#!/usr/bin/env python3
"""Surgically add the NET_STATUS publisher to a pristine network_manager.c.

Reads the pristine file from git HEAD and inserts only the new code, so all
pre-existing bytes (including any mangled comment characters) are preserved
exactly. This avoids line-ending / encoding churn in the generated patch.
"""
import subprocess
import sys

REPO = "/mnt/c/openvela_ws/openvela/packages/ai_agent"
REL = "src/infra/network_manager.c"

pristine = subprocess.check_output(
    ["git", "-C", REPO, "show", "HEAD:" + REL]
).decode("utf-8", "surrogateescape")

# 1) add <stdio.h> include
anchor_inc = "#include <netinet/in.h>\n"
assert pristine.count(anchor_inc) == 1, "include anchor"
pristine = pristine.replace(
    anchor_inc, anchor_inc + "#include <stdio.h>\n", 1
)

# 2) add agent_config.h + publisher after the s_ip_str declaration
anchor_decl = 'static char s_ip_str[INET_ADDRSTRLEN] = "0.0.0.0";\n'
assert pristine.count(anchor_decl) == 1, "decl anchor"
publisher = anchor_decl + '''
static int s_last_published_state = -1; /* -1 = unknown, 0 = down, 1 = up */

/* Publish the current network state to a file so that a separate process
 * (the zhaoxi_ui LVGL task) can display it without calling into this
 * module.  The UI reads the first line: "CONNECTED <ip>" or
 * "DISCONNECTED".  Only writes on state change to avoid hammering the
 * filesystem from the 500 ms polling paths.  Failure is never fatal.
 */
static void network_publish_status(bool connected)
{
    int state = connected ? 1 : 0;
    if (state == s_last_published_state) {
        return;
    }

    FILE* f = fopen(AGENT_DATA_DIR "/NET_STATUS", "w");
    if (f == NULL) {
        return;
    }

    if (connected) {
        fprintf(f, "CONNECTED %s\\n", s_ip_str);
    } else {
        fprintf(f, "DISCONNECTED\\n");
    }

    fclose(f);
    s_last_published_state = state;
}
'''
pristine = pristine.replace(anchor_decl, publisher, 1)

# 3) include agent_config.h for AGENT_DATA_DIR (next to network_manager.h)
anchor_hdr = '#include "network_manager.h"\n'
assert pristine.count(anchor_hdr) == 1, "hdr anchor"
pristine = pristine.replace(
    anchor_hdr, anchor_hdr + '#include "agent_config.h"\n', 1
)

# 4) publish on the two return paths of network_is_connected()
old_true = """            freeifaddrs(ifa_list);
            return true;"""
assert pristine.count(old_true) == 1, "true path"
pristine = pristine.replace(
    old_true,
    """            freeifaddrs(ifa_list);
            network_publish_status(true);
            return true;""",
    1,
)
old_false = """        freeifaddrs(ifa_list);
    }

    return false;
}

int network_wait_connected"""
assert pristine.count(old_false) == 1, "false path"
pristine = pristine.replace(
    old_false,
    """        freeifaddrs(ifa_list);
    }

    network_publish_status(false);
    return false;
}

int network_wait_connected""",
    1,
)

with open(REPO + "/" + REL, "w", encoding="utf-8", newline="") as fh:
    fh.write(pristine)

print("OK: patched", REL)

